  for c in cases {var state=c.seed,draws=0;let result=NativeSourceTntTargetSort.select(candidateIDs:(0..<c.n).map(String.init),random:{state=state &* 1664525 &+ 1013904223;draws+=1;return Double(state)/4294967296},current:{true});XCTAssertEqual(result,c.selected.map(String.init),"n=\(c.n) seed=\(c.seed)");XCTAssertEqual(draws,c.draws);XCTAssertEqual(state,c.state)}
 }
 func testGenerationRetirementInsideRandomStopsWithoutAdditionalDraws() {
  var live=true,draws=0;let result=NativeSourceTntTargetSort.select(candidateIDs:["a","b","c"],random:{draws+=1;live=false;return 0.25},current:{live});XCTAssertNil(result);XCTAssertEqual(draws,1)
 }
 func testUnsupportedRosterAndRetiredOwnerRefuseBeforeMath() {
  var draws=0;let random:()->Double={draws+=1;return 0.25}
  XCTAssertNil(NativeSourceTntTargetSort.select(candidateIDs:(0..<64).map(String.init),random:random,current:{true}));XCTAssertNil(NativeSourceTntTargetSort.select(candidateIDs:["a","b"],random:random,current:{false}));XCTAssertEqual(draws,0)
 }
}
